const fs=require("fs"),path=require("path"),RAW_FILE="karttakohteet_raw.json",OUTPUT_FILE="paikat_insert.sql",DEFAULT_MUNICIPALITY="Laukaa";try{const e=fs.readFileSync(RAW_FILE,"utf-8"),t=JSON.parse(e);let a="-- Paikkarekisterin data generoituna karttakohteet_raw.json -tiedostosta\n\n",r=0;t.features.forEach(e=>{const t=e.properties,i=e.geometry;if(!t.name||!i||"Point"!==i.type)return;const o=t.name.replace(/'/g,"''");let n="Muu kohde";"pitch"===t.leisure?n="Urheilukenttä":"school"===t.amenity?n="Koulu":"library"===t.amenity?n="Kirjasto":"place_of_worship"===t.amenity?n="Kirkko/Kappeli":"clinic"===t.amenity?n="Terveyskeskus":"attraction"===t.tourism?n="Nähtävyys":"park"===t.leisure?n="Puisto":"beach"!==t.natural&&"beachvolleyball"!==t.sport||(n="Uimaranta");const s=i.coordinates[1],l=i.coordinates[0],c=t["@id"]||t.id||"";let u=t["addr:city"]||"Laukaa";a+="INSERT INTO places (name, type, lat, lon, municipality, source, source_id) ",a+=`VALUES ('${o}', '${n}', ${s}, ${l}, '${u}', 'OSM_raw', '${c}');\n`,r++}),fs.writeFileSync(OUTPUT_FILE,a),console.log(`Generoitiin ${r} paikan SQL INSERT -lauseet tiedostoon ${OUTPUT_FILE}`)}catch(e){console.error("Virhe:",e)}